fl = {(f['level'], f['room']): f for f in F if f['kind'] == 'floor'}
for (lv, nm), f in sorted(fl.items()):
    area = sum((r[2] - r[0]) * (r[3] - r[1]) for r in f['rects'])
    c = [x for x in F if x['kind'] == 'ceiling' and x['level'] == lv and x['room'] == nm]
    hole = [x for x in F if x['kind'] == 'ceiling' and x['level'] == lv and x['room'] == nm + ' (หลุมฝ้า)']
    strip = [x for x in F if x['kind'] == 'ceiling' and x['level'] == lv and x['room'] == nm + ' (ขอบตั้งหลุมฝ้า)']
    cor = [x for x in F if x['kind'] == 'other' and x['level'] == lv and x['room'] == nm]
    where = f'{nm} ชั้น {lv[0]} (+{f["z"]:.2f}) {loc(f["rects"])}'
    L.append(f'| พื้น | {where} | {f["spec"].split()[1]} | {area:.2f} ตร.ม. | อ่านจากแบบ | |')
    if c:
        cc = c[0]; ca = sum((r[2] - r[0]) * (r[3] - r[1]) for r in cc['rects']); code = 'C2' if 'C2' in cc['spec'] else 'C1'
        t = f'{ca:.2f} ตร.ม. ที่ +{cc["z"] - f["z"]:.2f} (z {cc["z"]:.2f})'
        if hole:
            h = hole[0]['rects'][0]; t += f' · หลุม {h[2]-h[0]:.2f}×{h[3]-h[1]:.2f} ที่ +{hole[0]["z"] - f["z"]:.2f} · ขอบตั้ง {strip[0]["qty"]:.2f} ตร.ม.'
        L.append(f'| ฝ้า | {nm} ชั้น {lv[0]} | {code} | {t} | {ST[cc["status"]]} | {cc.get("note", "")} |')
    if cor: L.append(f'| บัวฝ้า | {nm} ชั้น {lv[0]} | บัวฝ้าสำเร็จรูป | {cor[0]["qty"]:.2f} ม. | {ST[cor[0]["status"]]} | ขนาดบัวแบบไม่ระบุ |')
for x in F:
    if x['room'].startswith('โถงทางเข้า') and x['kind'] == 'ceiling' and x.get('rects') and 'หลุม' not in x['room']:
        L.append(f'| ฝ้า | โถงทางเข้า ชั้น 1 (+0.50/+0.55) GL E–F / 6–9 (ช่องโล่งสูง 2 ชั้น) | C1 | รอบ +7.15 · หลุม 2.15×2.70 ที่ +7.35 (วัดจาก +0.55 → z 7.70 / 7.90) | อ่านจากแบบ | แปลนฝ้าชั้นบน |')
    if x['id'] == 'SOF-01':
        a = sum((r[2] - r[0]) * (r[3] - r[1]) for r in x['rects'])
        L.append(f'| ฝ้าชายคา | ชายคาหลังคาชั้นบน รอบอาคาร | Conwood | {a:.2f} ตร.ม. ที่ +8.65 | ข้อกำหนด Earth | ระดับฝ้าชายคา +8.65 (ระดับหลังอะเส) แบบไม่ระบุ — Earth 30 ต.ค. ตกลง |')
